<script setup>
import {computed,ref,watch,onMounted} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {api,login,register,errorText} from './api.js'
import {safeLoginDestination} from './authNavigation.js'
import GoogleLoginButton from './GoogleLoginButton.vue'
import AppIcon from '../../components/AppIcon.vue'
const props=defineProps({initialRegister:Boolean}),router=useRouter(),route=useRoute()
const isRegister=computed(()=>props.initialRegister||route.path==='/register'),forgot=ref(false)
const fullName=ref(''),email=ref(''),password=ref(''),confirmPassword=ref(''),showPassword=ref(false),showConfirm=ref(false)
const busy=ref(false),message=ref(''),error=ref(''),video=ref(null),playing=ref(false)
const reasons={'password-changed':'Đổi mật khẩu thành công. Vui lòng đăng nhập bằng mật khẩu mới.','session-expired':'Phiên đã hết hạn hoặc bị thu hồi. Vui lòng đăng nhập lại.','session-unavailable':'Vui lòng đăng nhập lại để tiếp tục.','login-required':'Đăng nhập để sử dụng chức năng này.','google-failed':'Chưa hoàn tất đăng nhập Google. Vui lòng thử lại hoặc đăng nhập bằng email.'}
watch(()=>route.fullPath,()=>{message.value=route.query.registered==='1'?'Tạo tài khoản thành công. Bạn có thể đăng nhập ngay.':reasons[route.query.reason]||'';error.value='';forgot.value=false},{immediate:true})
const heading=computed(()=>forgot.value?'Khôi phục mật khẩu':isRegister.value?'Bắt đầu cùng SmartProp':'Chào mừng bạn trở lại')
function switchTab(path){if(!busy.value)router.push(path)}
async function toggleVideo(){if(!video.value)return;if(playing.value){video.value.pause();playing.value=false}else{try{await video.value.play();playing.value=true}catch{playing.value=false}}}
onMounted(()=>{if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)toggleVideo()})
async function submit(){
 if(busy.value)return;error.value=message.value=''
 if(!forgot.value&&new TextEncoder().encode(password.value).length>72){error.value='Mật khẩu tối đa 72 byte UTF-8. Vui lòng kiểm tra lại.';return}
 if(isRegister.value&&!forgot.value&&password.value!==confirmPassword.value){error.value='Mật khẩu xác nhận không khớp.';return}
 busy.value=true
 try{
  if(forgot.value){await api('/auth/password/forgot',{method:'POST',body:{email:email.value.trim()},authenticated:false});message.value='Nếu tài khoản đủ điều kiện, liên kết đặt lại mật khẩu sẽ được gửi đến email của bạn.'}
  else if(isRegister.value){await register({fullName:fullName.value.trim(),email:email.value,password:password.value,role:'BUYER'});password.value=confirmPassword.value='';await router.replace({path:'/login',query:{registered:'1'}})}
  else{const user=await login(email.value,password.value,false);password.value='';await router.replace(safeLoginDestination(route.query.next,user.role))}
 }catch(e){error.value=errorText(e)}finally{busy.value=false}
}
</script>
<template>
 <main class="auth-scene"><video ref="video" class="auth-background" src="/background.mp4" poster="/media/home/hero-poster.jpg" loop muted playsinline aria-hidden="true"/><div class="auth-shade"/>
  <div class="auth-layout"><section class="auth-intro" aria-label="SmartProp"><RouterLink to="/home" class="auth-brand"><span>S</span>SmartProp.</RouterLink><div class="auth-intro-copy"><p>ĐÀ NẴNG · SMARTPROP</p><h1>Không gian sống.<br/><em>Khởi đầu của bạn.</em></h1><p>Khám phá bất động sản, lưu những lựa chọn yêu thích và tìm hiểu giá trị từ dữ liệu.</p></div><button type="button" class="auth-video-control" :aria-pressed="playing" @click="toggleVideo">{{playing?'Ⅱ Tạm dừng nền':'▷ Phát video nền'}}</button></section>
   <section class="auth-card" :aria-busy="busy" aria-labelledby="auth-heading"><RouterLink to="/home" class="auth-home">← Trang chủ SmartProp</RouterLink>
    <div v-if="!forgot" class="auth-tabs" role="tablist" aria-label="Đăng nhập hoặc đăng ký"><button type="button" role="tab" :aria-selected="!isRegister" :disabled="busy" @click="switchTab('/login')">Đăng nhập</button><button type="button" role="tab" :aria-selected="isRegister" :disabled="busy" @click="switchTab('/register')">Đăng ký</button></div>
    <button v-else type="button" class="auth-back" @click="forgot=false;message=error=''">← Quay lại đăng nhập</button>
    <div class="auth-titles"><h2 id="auth-heading">{{heading}}</h2><p>{{forgot?'Nhập email để nhận liên kết đặt lại mật khẩu.':isRegister?'Một tài khoản cho mọi trải nghiệm của bạn.':'Đăng nhập để tiếp tục từ những điều bạn quan tâm.'}}</p></div>
    <p v-if="message" role="status" class="auth-message auth-success">{{message}}</p><p v-if="error" role="alert" class="auth-message auth-error">{{error}}</p>
    <div v-if="isRegister&&!forgot" class="auth-information"><AppIcon name="shield"/><div><strong>Thông tin tài khoản</strong><p>Tài khoản mới có quyền người dùng thông thường. Để đăng bán hoặc cho thuê, bạn có thể đăng ký quyền đăng tin trong Hồ sơ cá nhân và chờ quản trị viên xét duyệt.</p></div></div>
    <form class="auth-form" @submit.prevent="submit"><label v-if="isRegister&&!forgot" class="auth-field" for="name-input">Họ và tên<input id="name-input" v-model="fullName" type="text" autocomplete="name" required maxlength="100" placeholder="Họ và tên của bạn" :disabled="busy"/></label>
     <label class="auth-field" for="email-input">{{!isRegister&&!forgot?'Email / tên quản trị':'Email'}}<input id="email-input" v-model="email" :type="!isRegister&&!forgot?'text':'email'" :autocomplete="!isRegister&&!forgot?'username':'email'" maxlength="254" required :placeholder="!isRegister&&!forgot?'Email hoặc Admin':'ban@email.com'" :disabled="busy"/></label>
     <div v-if="!forgot" class="auth-field"><label for="password-input">Mật khẩu</label><div class="auth-password"><input id="password-input" v-model="password" :type="showPassword?'text':'password'" :autocomplete="isRegister?'new-password':'current-password'" :minlength="isRegister?8:undefined" maxlength="72" required :placeholder="isRegister?'Tối thiểu 8 ký tự':'Nhập mật khẩu'" :disabled="busy"/><button type="button" :aria-label="showPassword?'Ẩn mật khẩu':'Hiện mật khẩu'" :aria-pressed="showPassword" @click="showPassword=!showPassword">{{showPassword?'Ẩn':'Hiện'}}</button></div><p v-if="isRegister" class="auth-hint">Từ 8 ký tự, tối đa 72 byte UTF-8.</p></div>
     <div v-if="isRegister&&!forgot" class="auth-field"><label for="confirm-password-input">Xác nhận mật khẩu</label><div class="auth-password"><input id="confirm-password-input" v-model="confirmPassword" :type="showConfirm?'text':'password'" autocomplete="new-password" minlength="8" maxlength="72" required placeholder="Nhập lại mật khẩu" :disabled="busy"/><button type="button" :aria-label="showConfirm?'Ẩn mật khẩu xác nhận':'Hiện mật khẩu xác nhận'" :aria-pressed="showConfirm" @click="showConfirm=!showConfirm">{{showConfirm?'Ẩn':'Hiện'}}</button></div></div>
     <button v-if="!isRegister&&!forgot" type="button" class="auth-forgot" @click="forgot=true;error=message=''">Quên mật khẩu?</button>
     <button type="submit" class="auth-submit" :disabled="busy">{{busy?'Đang xử lý…':forgot?'Gửi liên kết đặt lại':isRegister?'Tạo tài khoản':'Đăng nhập'}}</button>
    </form><GoogleLoginButton v-if="!forgot" :disabled="busy"/>
    <p class="auth-footnote">Tiếp tục khám phá không gian sống cùng SmartProp.</p>
   </section></div>
 </main>
</template>
<style scoped>
.auth-scene{position:relative;isolation:isolate;min-height:100svh;background:#10233f;color:#10233f;display:flex;align-items:center;padding:40px 32px}.auth-background,.auth-shade{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}.auth-shade{z-index:-1;background:linear-gradient(100deg,#07182de0,#0c234475 55%,#07182d9c)}.auth-layout{display:grid;grid-template-columns:1fr 480px;gap:70px;width:min(1200px,100%);margin:auto;align-items:center}.auth-intro{align-self:stretch;display:flex;flex-direction:column;justify-content:space-between;min-height:620px;padding:16px 0;color:white}.auth-brand{display:inline-flex;align-items:center;gap:12px;font-size:26px;font-weight:650;width:fit-content}.auth-brand>span{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:#fff;color:#10233f;font-size:25px}.auth-intro-copy>p:first-child{font-size:12px;letter-spacing:.18em;font-weight:600;color:#e7c58e;margin-bottom:20px}.auth-intro-copy h1{font-size:clamp(34px,4vw,58px);line-height:1.25;letter-spacing:-.04em;font-weight:500}.auth-intro-copy em{font-family:Georgia,serif;font-style:normal;color:#e7c58e}.auth-intro-copy>p:last-child{font-size:16px;line-height:1.9;color:#e2e8f0;max-width:420px;margin-top:22px}.auth-video-control{display:block;width:fit-content;margin-top:35px;padding:10px 16px;border:1px solid #ffffff66;border-radius:999px;font-size:13px;color:white}.auth-card{padding:32px;border:1px solid #ffffff60;border-radius:26px;background:#fffffff5;box-shadow:0 25px 90px #00102a40;backdrop-filter:blur(20px);min-width:0}.auth-home,.auth-back{font-size:13px;color:#536178;text-decoration:none;display:inline-block;margin-bottom:20px}.auth-tabs{display:flex;gap:4px;background:#eeeae3;border-radius:14px;padding:5px}.auth-tabs button{width:50%;padding:11px 8px;border-radius:10px;font-size:14px;font-weight:600;color:#536178}.auth-tabs button[aria-selected=true]{background:white;color:#10233f;box-shadow:0 3px 8px #10233f0d}.auth-titles{margin:25px 0}.auth-titles h2{font-size:28px;line-height:1.3;letter-spacing:-.025em;font-weight:650}.auth-titles p{font-size:14px;line-height:1.7;color:#536178;margin-top:10px}.auth-form{display:grid;gap:17px}.auth-field{display:flex;flex-direction:column;gap:8px;font-size:14px;font-weight:550;min-width:0}.auth-field input{width:100%;min-width:0;min-height:48px;padding:12px 14px;border:1px solid #cdd3dc;border-radius:12px;background:white;color:#10233f;font-size:15px;font-weight:400;outline:none}.auth-password{position:relative;display:flex;align-items:center}.auth-password input{padding-right:64px}.auth-password button{position:absolute;right:6px;min-width:48px;min-height:38px;padding:8px;color:#536178;font-size:13px}.auth-field input:focus-visible{border-color:#8b683a;outline:3px solid #d9c5a780;outline-offset:1px}.auth-hint{font-size:13px;line-height:1.5;color:#536178;font-weight:400}.auth-forgot{justify-self:end;color:#536178;font-size:13px;text-decoration:underline}.auth-submit{min-height:48px;margin-top:3px;border-radius:12px;background:#10233f;color:white;font-size:15px;font-weight:600;transition:background .15s}.auth-submit:hover:enabled{background:#24456d}.auth-submit:disabled{opacity:.6;cursor:wait}.auth-information{display:flex;gap:12px;margin-bottom:21px;padding:15px;border:1px solid #dce3e9;border-radius:14px;background:#f0f4f7}.auth-information strong{font-size:13px;font-weight:650}.auth-information p{font-size:13px;line-height:1.7;color:#536178;margin-top:4px}.auth-message{padding:13px 15px;border-radius:12px;font-size:14px;line-height:1.7;margin-bottom:18px}.auth-success{background:#eaf5ee;color:#1c6347}.auth-error{background:#fff0eb;color:#8d302d}.auth-footnote{text-align:center;margin-top:22px;font-size:12px;color:#536178}.auth-scene button:focus-visible,.auth-scene a:focus-visible{outline:3px solid #b3915f;outline-offset:3px}@media(max-width:1000px){.auth-layout{grid-template-columns:1fr 460px;gap:28px}.auth-intro-copy h1{font-size:38px}}@media(max-width:767px){.auth-scene{padding:24px 16px}.auth-layout{display:block;max-width:480px}.auth-intro{min-height:0;display:none}.auth-card{padding:26px 22px;border-radius:22px}.auth-titles h2{font-size:27px}.auth-field input{font-size:16px}.auth-titles{margin-block:22px}}
</style>
